interface.definition:
{
  a!localVariables(
    local!user: loggedInUser(),
    local!team: #"_a-0000eff6-70cf-8000-9e5f-011c48011c48_1351393"(assginedto: local!user),
    local!numCols: 3,
    local!showrejectiondetails: false(),
    local!comment,
    /* Change this to set a different number of columns. If you change this number, consider updating the stackWhen parameter on the columns layout */
    local!selectedCard,
    {
      #"SYSTEM_SYSRULES_columnsLayout"(
        columns: #"SYSTEM_SYSRULES_forEach"(
          items: enumerate(local!numCols) + 1,
          expression: a!localVariables(
            local!colIndex: fv!index,
            #"SYSTEM_SYSRULES_columnLayout"(
              contents: {
                #"SYSTEM_SYSRULES_forEach"(
                  items: local!team,
                  expression: #"SYSTEM_SYSRULES_cardLayout"(
                    contents: {
                      #"SYSTEM_SYSRULES_cardLayout"(
                        contents: {
                          #"SYSTEM_SYSRULES_columnsLayout"(
                            columns: {
                              #"SYSTEM_SYSRULES_columnLayout"(
                                contents: {
                                  #"SYSTEM_SYSRULES_richTextDisplayField"(
                                    labelPosition: "COLLAPSED",
                                    value: {
                                      #"SYSTEM_SYSRULES_richTextItem_v1"(
                                        text: a!defaultValue(
                                          index(fv!item, "RequestedBy", null()),
                                          "-"
                                        ),
                                        style: "STRONG"
                                      )
                                    }
                                  ),
                                  #"SYSTEM_SYSRULES_richTextDisplayField"(
                                    labelPosition: "COLLAPSED",
                                    marginAbove: "EVEN_LESS",
                                    value: {
                                      #"SYSTEM_SYSRULES_richTextItem_v1"(
                                        text: index(fv!item, "RequestedOn", null()),
                                        size: "SMALL"
                                      )
                                    }
                                  )
                                },
                                width: "7X"
                              ),
                              #"SYSTEM_SYSRULES_columnLayout"(
                                contents: {
                                  #"SYSTEM_SYSRULES_tagField"(
                                    tags: {
                                      if(
                                        #"_a-0000ef67-4afa-8000-9e56-011c48011c48_1204747"[1] = tointeger(index(fv!item, "taskdef", null())),
                                        #"SYSTEM_SYSRULES_tagItem_v1"(text: "ADD", backgroundColor: "POSITIVE"),
                                        #"SYSTEM_SYSRULES_tagItem_v1"(
                                          text: "REVOKE",
                                          backgroundColor: "NEGATIVE"
                                        )
                                      )
                                    }
                                  )
                                },
                                width: "3X"
                              )
                            }
                          ),
                          #"SYSTEM_SYSRULES_horizontalLine"(),
                          #"SYSTEM_SYSRULES_columnsLayout"(
                            columns: {
                              #"SYSTEM_SYSRULES_columnLayout"(
                                contents: {
                                  #"SYSTEM_SYSRULES_richTextDisplayField"(
                                    labelPosition: "COLLAPSED",
                                    marginAbove: "EVEN_LESS",
                                    value: {
                                      #"SYSTEM_SYSRULES_richTextIcon"(icon: "building"),
                                      #"SYSTEM_SYSRULES_richTextItem_v1"(text: " "),
                                      #"SYSTEM_SYSRULES_richTextItem_v1"(
                                        text: "Org  ",
                                        style: "STRONG",
                                        color: "SECONDARY"
                                      )
                                    }
                                  ),
                                  #"SYSTEM_SYSRULES_richTextDisplayField"(
                                    labelPosition: "COLLAPSED",
                                    marginAbove: "EVEN_LESS",
                                    value: {
                                      #"SYSTEM_SYSRULES_richTextIcon"(icon: "users"),
                                      #"SYSTEM_SYSRULES_richTextItem_v1"(text: " "),
                                      #"SYSTEM_SYSRULES_richTextItem_v1"(
                                        text: "Team ",
                                        style: "STRONG",
                                        color: "SECONDARY"
                                      )
                                    }
                                  ),
                                  #"SYSTEM_SYSRULES_richTextDisplayField"(
                                    labelPosition: "COLLAPSED",
                                    marginAbove: "EVEN_LESS",
                                    value: {
                                      #"SYSTEM_SYSRULES_richTextIcon"(icon: "users-cog"),
                                      #"SYSTEM_SYSRULES_richTextItem_v1"(text: " "),
                                      #"SYSTEM_SYSRULES_richTextItem_v1"(
                                        text: "Role ",
                                        color: "SECONDARY",
                                        style: "STRONG"
                                      )
                                    }
                                  )
                                }
                              ),
                              #"SYSTEM_SYSRULES_columnLayout"(
                                contents: {
                                  #"SYSTEM_SYSRULES_richTextDisplayField"(
                                    value: {
                                      #"SYSTEM_SYSRULES_richTextItem_v1"(text: index(fv!item, "OrgName", null()))
                                    }
                                  ),
                                  #"SYSTEM_SYSRULES_richTextDisplayField"(
                                    value: {
                                      #"SYSTEM_SYSRULES_richTextItem_v1"(text: index(fv!item, "TeamName", null()))
                                    }
                                  ),
                                  #"SYSTEM_SYSRULES_tagField"(
                                    tags: #"SYSTEM_SYSRULES_forEach"(
                                      items: split(index(fv!item, "rolegroups", null()), ";"),
                                      expression: #"SYSTEM_SYSRULES_tagItem_v1"(
                                        text: trim(fv!item),
                                        backgroundColor: "#a8e3b8"
                                      )
                                    )
                                  )
                                }
                              )
                            }
                          ),
                          #"SYSTEM_SYSRULES_horizontalLine"(),
                          if(
                            #"_a-0000ef67-4afa-8000-9e56-011c48011c48_1204747"[1] = tointeger(index(fv!item, "taskdef", null())),
                            {
                              /* Primary action buttons - hidden while entering a rejection reason */
                              #"SYSTEM_SYSRULES_ButtonArrayLayout"(
                                align: "END",
                                buttons: {
                                  #"SYSTEM_SYSRULES_buttonWidget_v1"(
                                    label: "Reject",
                                    style: "OUTLINE",
                                    color: "NEGATIVE",
                                    /*showWhen: if(*/
                                      /*tointeger(local!selectedCard) = fv!index,*/
                                      /*not(local!showrejectiondetails),*/
                                      /*local!showrejectiondetails*/
                                    /*),*/
                                    saveInto: {
                                      a!save(local!showrejectiondetails, true()),
                                      a!save(local!selectedCard, fv!index)
                                    }
                                  ),
                                  #"SYSTEM_SYSRULES_buttonWidget_v1"(
                                    label: "Accept",
                                    style: "SOLID",
                                    color: "ACCENT",
                                    /*showWhen: if(*/
                                      /*tointeger(local!selectedCard) = fv!index,*/
                                      /*not(local!showrejectiondetails),*/
                                      /*local!showrejectiondetails*/
                                    /*),*/
                                    saveInto: {
                                      #"SYSTEM_SYSRULES_startProcess_v2"(
                                        processModel: #"_a-0000eff6-70cf-8000-9e5f-011c48011c48_1351758",
                                        processParameters: {
                                          acceptaction: #"_a-0000ef67-4afa-8000-9e56-011c48011c48_1205572",
                                          orgid: index(fv!item, "orgid", null()),
                                          teamids: index(fv!item, "teamid", null()),
                                          taskid: index(fv!item, "taskid", null())
                                        },
                                        isSynchronous: true(),
                                        onSuccess: {
                                          a!save(
                                            local!team,
                                            #"_a-0000eff6-70cf-8000-9e5f-011c48011c48_1351393"(assginedto: local!user)
                                          )
                                        }
                                      ),

                                    }
                                  )
                                }
                              ),
                              /* Rejection reason panel - sibling of the button array, shown on Reject */
                              #"SYSTEM_SYSRULES_textField"(
                                showWhen: and(
                                  local!showrejectiondetails,
                                  tointeger(local!selectedCard) = fv!index
                                ),
                                label: "Reason for Rejection",
                                refreshAfter: "KEYPRESS",
                                characterLimit: 255,
                                showCharacterCount: true,
                                value: local!comment,
                                required: true(),
                                saveInto: a!save(local!comment, save!value)
                              ),
                              #"SYSTEM_SYSRULES_ButtonArrayLayout"(
                                align: "END",
                                showWhen: and(
                                  local!showrejectiondetails,
                                  tointeger(local!selectedCard) = fv!index
                                ),
                                buttons: {
                                  #"SYSTEM_SYSRULES_buttonWidget_v1"(
                                    label: "Cancel",
                                    icon: "pencil-ruler",
                                    style: "OUTLINE",
                                    color: "NEGATIVE",
                                    saveInto: {
                                      a!save(local!showrejectiondetails, false()),
                                      a!save(local!comment, null())
                                    }
                                  ),
                                  #"SYSTEM_SYSRULES_buttonWidget_v1"(
                                    label: "Submit Rejection",
                                    icon: "thumbs-o-up",
                                    style: "SOLID",
                                    color: "ACCENT",
                                    saveInto: {
                                      #"SYSTEM_SYSRULES_startProcess_v2"(
                                        processModel: #"_a-0000eff6-70cf-8000-9e5f-011c48011c48_1351758",
                                        processParameters: {
                                          acceptaction: #"_a-0000ef67-4afa-8000-9e56-011c48011c48_1205579",
                                          orgid: index(fv!item, "orgid", null()),
                                          teamids: index(fv!item, "teamid", null()),
                                          taskid: index(fv!item, "taskid", null()),
                                          comment: local!comment,

                                        },
                                        isSynchronous: true(),
                                        onSuccess: {
                                          a!save(
                                            local!team,
                                            #"_a-0000eff6-70cf-8000-9e5f-011c48011c48_1351393"(assginedto: local!user)
                                          )
                                        }
                                      )
                                    }
                                  )
                                }
                              )
                            },
                            /*revoke flow*/
                            {
                              /* Primary action buttons - hidden while entering a rejection reason */
                              #"SYSTEM_SYSRULES_ButtonArrayLayout"(
                                align: "END",
                                buttons: {
                                  #"SYSTEM_SYSRULES_buttonWidget_v1"(
                                    label: "Reject",
                                    style: "OUTLINE",
                                    color: "NEGATIVE",
                                    /*showWhen: if(*/
                                      /*tointeger(local!selectedCard) = fv!index,*/
                                      /*not(local!showrejectiondetails),*/
                                      /*local!showrejectiondetails*/
                                    /*),*/
                                    saveInto: {
                                      a!save(local!showrejectiondetails, true()),
                                      a!save(local!selectedCard, fv!index)
                                    }
                                  ),
                                  #"SYSTEM_SYSRULES_buttonWidget_v1"(
                                    label: "Accept",
                                    style: "SOLID",
                                    color: "ACCENT",
                                    /*showWhen: if(*/
                                      /*tointeger(local!selectedCard) = fv!index,*/
                                      /*not(local!showrejectiondetails),*/
                                      /*local!showrejectiondetails*/
                                    /*),*/
                                    saveInto: {
                                      #"SYSTEM_SYSRULES_startProcess_v2"(
                                        processModel: #"_a-0000eff6-70cf-8000-9e5f-011c48011c48_1352712",
                                        processParameters: {
                                          appectaction: #"_a-0000ef67-4afa-8000-9e56-011c48011c48_1205572",
                                          orgid: index(fv!item, "orgid", null()),
                                          teamids: index(fv!item, "teamid", null()),
                                          taskid: index(fv!item, "taskid", null())
                                        },
                                        isSynchronous: true(),
                                        onSuccess: {
                                          a!save(
                                            local!team,
                                            #"_a-0000eff6-70cf-8000-9e5f-011c48011c48_1351393"(assginedto: local!user)
                                          )
                                        }
                                      ),

                                    }
                                  )
                                }
                              ),
                              /* Rejection reason panel - sibling of the button array, shown on Reject */
                              #"SYSTEM_SYSRULES_textField"(
                                showWhen: and(
                                  local!showrejectiondetails,
                                  tointeger(local!selectedCard) = fv!index
                                ),
                                label: "Reason for Rejection",
                                refreshAfter: "KEYPRESS",
                                characterLimit: 255,
                                showCharacterCount: true,
                                value: local!comment,
                                required: true(),
                                saveInto: a!save(local!comment, save!value)
                              ),
                              #"SYSTEM_SYSRULES_ButtonArrayLayout"(
                                align: "END",
                                showWhen: and(
                                  local!showrejectiondetails,
                                  tointeger(local!selectedCard) = fv!index
                                ),
                                buttons: {
                                  #"SYSTEM_SYSRULES_buttonWidget_v1"(
                                    label: "Cancel",
                                    icon: "pencil-ruler",
                                    style: "OUTLINE",
                                    color: "NEGATIVE",
                                    saveInto: {
                                      a!save(local!showrejectiondetails, false()),
                                      a!save(local!comment, null())
                                    }
                                  ),
                                  #"SYSTEM_SYSRULES_buttonWidget_v1"(
                                    label: "Submit Rejection",
                                    icon: "thumbs-o-up",
                                    style: "SOLID",
                                    color: "ACCENT",
                                    saveInto: {
                                      #"SYSTEM_SYSRULES_startProcess_v2"(
                                        processModel: #"_a-0000eff6-70cf-8000-9e5f-011c48011c48_1352712",
                                        processParameters: {
                                          appectaction: #"_a-0000ef67-4afa-8000-9e56-011c48011c48_1205579",
                                          orgid: index(fv!item, "orgid", null()),
                                          teamids: index(fv!item, "teamid", null()),
                                          taskid: index(fv!item, "taskid", null()),
                                          comment: local!comment,

                                        },
                                        isSynchronous: true(),
                                        onSuccess: {
                                          a!save(
                                            local!team,
                                            #"_a-0000eff6-70cf-8000-9e5f-011c48011c48_1351393"(assginedto: local!user)
                                          )
                                        }
                                      )
                                    }
                                  )
                                }
                              )
                            }
                          )
                        },
                        showBorder: false,
                        padding: "LESS",
                        height: "AUTO"
                      )
                    },
                    /* This logic assigns each card to the right column */
                    showWhen: or(
                      mod(fv!index, local!numCols) = local!colIndex,
                      and(
                        mod(fv!index, local!numCols) = 0,
                        local!colIndex = local!numCols
                      )
                    ),
                    marginBelow: "STANDARD",
                    padding: "STANDARD"
                  )
                )
              }
            )
          )
        ),
        stackWhen: { "PHONE", "TABLET_PORTRAIT" },
        alignVertical: "TOP"
      ),

    }
  )
}
